  const editAssetInfo=defaultName=>new Promise(resolve=>{const modal=document.createElement('div');modal.className='trace-modal';modal.innerHTML=`<form class="trace-panel" style="width:min(480px,94vw)"><div class="trace-head"><h2>沉淀为资产</h2><button type="button" data-close>关闭</button></div><label>资产名称<input name="name" required maxlength="80"></label><div>资产类型<div class="asset-kind-options"><label class="asset-kind-option"><input type="radio" name="kind" value="character" checked><span><strong>角色</strong><span>人物身份、外貌与服装参考</span></span></label><label class="asset-kind-option"><input type="radio" name="kind" value="location"><span><strong>场景</strong><span>地点、空间布局与环境参考</span></span></label><label class="asset-kind-option"><input type="radio" name="kind" value="prop"><span><strong>道具</strong><span>需要跨镜头保持一致的物品</span></span></label><label class="asset-kind-option"><input type="radio" name="kind" value="style"><span><strong>画风</strong><span>色彩、材质、灯光与整体视觉风格</span></span></label></div></div><button type="submit">保存到资产</button></form>`;const form=modal.querySelector('form');form.elements.name.value=defaultName;const finish=value=>{modal.remove();resolve(value)};modal.querySelector('[data-close]').onclick=()=>finish(null);modal.onclick=event=>{if(event.target===modal)finish(null)};form.onsubmit=event=>{event.preventDefault();finish({name:form.elements.name.value.trim(),kind:new FormData(form).get('kind')})};document.body.append(modal);form.elements.name.focus();form.elements.name.select()});
