      return {id:assetId,name:libraryItem?.name||spec.name||entity.name||assetId,kind:libraryItem?.kind||spec.kind||entity.kind||'reference',source:sourceName[spec.source]||(libraryItem?'资产库':'未解析'),href:libraryItem?.href||spec.href||'',libraryId:libraryItem?.id||spec.library_asset_id||'',entityId:spec.entity_id||entity.id||''};
