    const shotCards=shotRows.length?shotRows.map(({shot,index,items,warnings})=>{const bindings=items.length?items.map(({assetId,role})=>{const asset=resolveAsset(assetId);return `<div class="trace-binding">${asset.href?`<img loading="lazy" src="${esc(assetUrl(asset.href))}" alt="">`:''}<div>${esc(asset.name)}<small>${esc(role)} · ${esc(asset.source)}</small></div></div>`}).join(''):'<span class="trace-binding">未绑定参考资产</span>';const mapping=(shot.generation_plan?.reference_mapping||[]).map(item=>{const asset=resolveAsset(item.asset_id);return `<div class="trace-binding"><div>&lt;${esc(item.picture)}&gt;<small>映射到 ${esc(asset.name)} · ${esc(item.asset_id)}</small></div></div>`}).join('');return `<article class="trace-shot"><div class="trace-shot-head"><h4>${esc(shot.id||`镜头 ${index+1}`)} · ${esc((shot.action||shot.prompt||'').slice(0,60))}</h4><span>${esc(shot.start_time_seconds??'')}–${esc(shot.end_time_seconds??'')} 秒</span></div><div class="trace-shot-assets">${bindings}</div>${mapping?`<div class="trace-shot-assets">${mapping}</div>`:''}${warnings.map(value=>`<div class="trace-warning">${esc(value)}</div>`).join('')}</article>`}).join(''):'<p>此任务没有故事板镜头。</p>';
    const sections=[['任务与节点',{id:task.id,status:task.status,message:task.message,progress:task.progress,nodes:task.nodes||[]}],['创作意图',task.creative_intent||plan.creative_intent||{}],['连续性设定',bible],['故事板',shots],['审片结果',task.review||null],['子生成任务',data.child_tasks||[]],['产物文件',data.artifact_files||[]]];
