  const kindName = kind => kind === 'image' ? '图片生成' : kind === 'ai_video' ? 'AI视频创作' : '视频生成';
  const card = data => { const el=document.createElement('article'); el.className='asset-card'; el.dataset.jobId=data.id||'';el.dataset.kind=data.kind||'video';el.dataset.status=data.status||'queued';el.innerHTML=`<div class="asset-preview asset-loading">处理中...</div><div><h3>${esc(kindName(data.kind))} · ${esc(data.status)}</h3><div class="asset-meta">${esc(data.prompt)}\n参考图：${esc(data.reference_image || '无')}\n参考视频：${esc(data.reference_video || '无')}\n参数：${esc(JSON.stringify(data.params || {}))}</div><div class="workflow-nodes"></div><div class="asset-actions"></div></div>`; feed.prepend(el);syncAssetView();return el; };
